export const wardrobeItems=['star','ribbon','sunglasses','silver-glasses','crown','santa','goggles','helmet','ski','board','bunny-ears','cat-ears','bear-ears','eyes-flat','eyes-round','eyes-goofy','eyes-sleepy','eyes-happy','eyes-star','eyes-heart','earmuffs'];
const head=['crown','santa','helmet','bunny-ears','cat-ears','bear-ears','earmuffs'],eyes=['eyes-flat','eyes-round','eyes-goofy','eyes-sleepy','eyes-happy','eyes-star','eyes-heart'],slots=[head,['sunglasses','silver-glasses','goggles'],['ski','board'],eyes];
export function selectedItems(value){return [...new Set(String(value||'').split(','))].filter(v=>wardrobeItems.includes(v));}
export function normalizeWardrobe(value){const items=selectedItems(value),winners=slots.map(slot=>{const chosen=items.filter(v=>slot.includes(v));if(slot===head&&chosen.includes('helmet'))return 'helmet';if(chosen.includes('goggles'))return 'goggles';if(chosen.includes('board'))return 'board';return chosen.at(-1);});return items.filter(v=>{const index=slots.findIndex(slot=>slot.includes(v));return index<0||v===winners[index];}).join(',')||'none';}
export function toggleItem(value,item){if(item==='none')return 'none';let items=selectedItems(value);if(items.includes(item))items=items.filter(v=>v!==item);else{const slot=slots.find(group=>group.includes(item));items=items.filter(v=>!slot?.includes(v));items.push(item);}return normalizeWardrobe(items.join(','));}
